local PortcullisMaker = {}
local PRODUCTS = {
    simple_iron_portcullis = { name = "Preprost železni padajoča rešetka", ironCost = 5, woodCost = 2, time = 8, cost = 320, defense = 42, happiness = 1, description = "Preprost železni padajoča rešetka za vhod." },
    steel_bar_portcullis = { name = "Jeklenotična padajoča rešetka", ironCost = 4, steelCost = 3, woodCost = 2, time = 11, cost = 760, defense = 58, happiness = 2, prestige = 3, description = "Jeklenotična padajoča rešetka za trgovce." },
    silver_chain_portcullis = { name = "Srebrnoverižna padajoča rešetka", ironCost = 4, steelCost = 2, silverCost = 2, woodCost = 2, time = 15, cost = 1800, defense = 72, happiness = 2, prestige = 8, description = "Srebrnoverižna padajoča rešetka za plemiče." },
    gold_trimmed_portcullis = { name = "Zlatookrasna padajoča rešetka", ironCost = 4, steelCost = 2, goldCost = 2, silverCost = 1, woodCost = 2, time = 19, cost = 4000, defense = 85, happiness = 3, prestige = 18, description = "Zlatookrasna padajoča rešetka za visoke plemiče." },
    jewel_pinned_portcullis = { name = "Draguljnoprity padajoča rešetka", ironCost = 4, steelCost = 2, goldCost = 2, silverCost = 1, woodCost = 2, jewelCost = 1, time = 23, cost = 8500, defense = 95, happiness = 5, prestige = 32, description = "Padajoča rešetka z draguljno priponko za visoko plemstvo." },
    royal_grand_portcullis = { name = "Kraljevski veliki padajoča rešetka", ironCost = 6, steelCost = 3, goldCost = 3, silverCost = 2, woodCost = 2, jewelCost = 2, pearlCost = 2, time = 30, cost = 17000, defense = 100, happiness = 13, prestige = 65, description = "Velika kraljevska padajoča rešetka z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    portcullis_workshop = { name = "Rešetkarska delavnica", cost = { gold = 340, wood = 140, stone = 180, iron = 8 }, upkeep = 8, qualityBonus = 5 },
    smithy_loft = { name = "Kovaška podstrešje", cost = { gold = 1200, wood = 280, stone = 320, steel = 6, silver = 6 }, upkeep = 28, qualityBonus = 18 },
    master_portcullis_atelier = { name = "Mojstrski rešetkarski atelje", cost = { gold = 3000, wood = 380, stone = 520, silver = 32, gold = 6 }, upkeep = 70, qualityBonus = 30 },
    royal_portcullis_palace = { name = "Kraljevska rešetkarska palača", cost = { gold = 13000, wood = 600, stone = 800, gold = 80, jewel = 18 }, upkeep = 260, qualityBonus = 55, prestigeBonus = 50 },
}
PortcullisMaker.ironStock = 20; PortcullisMaker.steelStock = 12; PortcullisMaker.woodStock = 14; PortcullisMaker.silverStock = 8; PortcullisMaker.goldStock = 6; PortcullisMaker.jewelStock = 4; PortcullisMaker.pearlStock = 4
PortcullisMaker.productStock = {}; PortcullisMaker.buildings = {}; PortcullisMaker.maker = nil; PortcullisMaker.activeMaking = {}; PortcullisMaker.totalProducts = 0; PortcullisMaker.dayTimer = 0
function PortcullisMaker.init() PortcullisMaker.ironStock=20; PortcullisMaker.steelStock=12; PortcullisMaker.woodStock=14; PortcullisMaker.silverStock=8; PortcullisMaker.goldStock=6; PortcullisMaker.jewelStock=4; PortcullisMaker.pearlStock=4; PortcullisMaker.productStock={}; PortcullisMaker.buildings={}; PortcullisMaker.maker=nil; PortcullisMaker.activeMaking={}; PortcullisMaker.totalProducts=0; PortcullisMaker.dayTimer=0; print("[PortcullisMaker] Royal Portcullis Maker System initialized (6 products, 4 buildings)") end
function PortcullisMaker.hireMaker(n,s) s=s or math.random(55,90); local c=640+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; PortcullisMaker.maker={name=n or ("Rešetkar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Rešetkar najet: %s (spretnost: %d)",PortcullisMaker.maker.name,s),"success") end; return true end
function PortcullisMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function PortcullisMaker.build(id) local ok,e=PortcullisMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(PortcullisMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function PortcullisMaker.getQualityBonus() local b=0; for _,bd in ipairs(PortcullisMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function PortcullisMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and PortcullisMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.steelCost and PortcullisMaker.steelStock<(d.steelCost or 0) then return false,"Premalo jekla" end; if d.woodCost and PortcullisMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.silverCost and PortcullisMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and PortcullisMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and PortcullisMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and PortcullisMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #PortcullisMaker.buildings==0 then return false,"Potrebna rešetkarska delavnica" end; if not PortcullisMaker.maker then return false,"Potreben rešetkar" end; return true end
function PortcullisMaker.make(pt,qty) qty=qty or 1; local ok,e=PortcullisMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then PortcullisMaker.ironStock=PortcullisMaker.ironStock-d.ironCost*qty end; if d.steelCost then PortcullisMaker.steelStock=PortcullisMaker.steelStock-d.steelCost*qty end; if d.woodCost then PortcullisMaker.woodStock=PortcullisMaker.woodStock-d.woodCost*qty end; if d.silverCost then PortcullisMaker.silverStock=PortcullisMaker.silverStock-d.silverCost*qty end; if d.goldCost then PortcullisMaker.goldStock=PortcullisMaker.goldStock-d.goldCost*qty end; if d.jewelCost then PortcullisMaker.jewelStock=PortcullisMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then PortcullisMaker.pearlStock=PortcullisMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if PortcullisMaker.maker then t=math.max(1,t-math.floor(PortcullisMaker.maker.skill/12)) end; table.insert(PortcullisMaker.activeMaking,{id="portcullis_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,defense=d.defense or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kovanje: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function PortcullisMaker.completeMaking(m) local q=1.0+(PortcullisMaker.getQualityBonus()/100); if PortcullisMaker.maker then q=q+(PortcullisMaker.maker.skill/140) end; q=math.min(2.5,q); PortcullisMaker.productStock[m.productType]=(PortcullisMaker.productStock[m.productType] or 0)+m.quantity; PortcullisMaker.totalProducts=PortcullisMaker.totalProducts+m.quantity; if m.defense>0 and _G.state then _G.state.defense=(_G.state.defense or 0)+m.defense end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if PortcullisMaker.maker then PortcullisMaker.maker.itemsMade=PortcullisMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then PortcullisMaker.maker.skill=math.min(100,PortcullisMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Rešetka izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"portcullis.completed",{productName=m.productName,defense=m.defense,prestige=m.prestige,happiness=m.happiness}) end end
function PortcullisMaker.update(dt) if not _G.state then return end; PortcullisMaker.dayTimer=PortcullisMaker.dayTimer+dt; if PortcullisMaker.dayTimer>=30 then PortcullisMaker.dayTimer=0; for i=#PortcullisMaker.activeMaking,1,-1 do local m=PortcullisMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then PortcullisMaker.completeMaking(m); table.remove(PortcullisMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(PortcullisMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if PortcullisMaker.maker then tu=tu+18 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function PortcullisMaker.getStats() return {ironStock=PortcullisMaker.ironStock,steelStock=PortcullisMaker.steelStock,woodStock=PortcullisMaker.woodStock,silverStock=PortcullisMaker.silverStock,goldStock=PortcullisMaker.goldStock,jewelStock=PortcullisMaker.jewelStock,pearlStock=PortcullisMaker.pearlStock,productStock=PortcullisMaker.productStock,numBuildings=#PortcullisMaker.buildings,hasMaker=PortcullisMaker.maker~=nil,makerName=PortcullisMaker.maker and PortcullisMaker.maker.name or "—",makerSkill=PortcullisMaker.maker and PortcullisMaker.maker.skill or 0,activeMaking=#PortcullisMaker.activeMaking,totalProducts=PortcullisMaker.totalProducts} end
return PortcullisMaker
